import { truncate } from './string';

describe('truncate', () => {
  describe('when string is shorter than maxLength', () => {
    it('should return original string', () => {
      expect(truncate('hello', 10)).toBe('hello');
    });

    it('should return original when exactly at maxLength', () => {
      expect(truncate('hello', 5)).toBe('hello');
    });
  });

  describe('when string needs truncation', () => {
    it('should truncate and add suffix', () => {
      expect(truncate('hello world', 8)).toBe('hello...');
    });

    it('should use custom suffix', () => {
      expect(truncate('hello world', 9, '---')).toBe('hello----');
    });

    it('should handle single char suffix', () => {
      expect(truncate('hello world', 6, '~')).toBe('hello~');
    });
  });

  describe('edge cases', () => {
    it('should handle empty string', () => {
      expect(truncate('', 5)).toBe('');
    });

    it('should handle maxLength of 0', () => {
      expect(truncate('hello', 0)).toBe('');
    });

    it('should handle maxLength smaller than suffix', () => {
      expect(truncate('hello world', 2)).toBe('..');
    });

    it('should handle maxLength equal to suffix length', () => {
      expect(truncate('hello world', 3)).toBe('...');
    });

    it('should handle empty suffix', () => {
      expect(truncate('hello world', 5, '')).toBe('hello');
    });
  });

  describe('unicode', () => {
    it('should handle unicode characters', () => {
      expect(truncate('hello 🌍 world', 9)).toBe('hello ...');
    });
  });
});
