import { createUser } from './userService';
import { db } from '../db';

jest.mock('../db');

const mockDb = db as jest.Mocked<typeof db>;

describe('createUser', () => {
  beforeEach(() => {
    jest.clearAllMocks();
  });

  describe('validation', () => {
    it('should throw error when email is empty', async () => {
      await expect(createUser({ email: '', name: 'John' }))
        .rejects.toThrow('Invalid email');
    });

    it('should throw error when email has no @', async () => {
      await expect(createUser({ email: 'invalid', name: 'John' }))
        .rejects.toThrow('Invalid email');
    });

    it('should throw error when name is too short', async () => {
      await expect(createUser({ email: 'john@test.com', name: 'J' }))
        .rejects.toThrow('Name too short');
    });

    it('should throw error when name is empty', async () => {
      await expect(createUser({ email: 'john@test.com', name: '' }))
        .rejects.toThrow('Name too short');
    });
  });

  describe('duplicate check', () => {
    it('should throw error when email already exists', async () => {
      mockDb.findUserByEmail.mockResolvedValue({ id: '1', email: 'john@test.com', name: 'John' });

      await expect(createUser({ email: 'john@test.com', name: 'John' }))
        .rejects.toThrow('Email already exists');
    });
  });

  describe('success', () => {
    it('should create user when data is valid', async () => {
      mockDb.findUserByEmail.mockResolvedValue(null);
      mockDb.createUser.mockResolvedValue({ id: '1', email: 'john@test.com', name: 'John' });

      const result = await createUser({ email: 'john@test.com', name: 'John' });

      expect(result).toEqual({ id: '1', email: 'john@test.com', name: 'John' });
      expect(mockDb.createUser).toHaveBeenCalledWith({ email: 'john@test.com', name: 'John' });
    });
  });
});
